  [279938] = { "罠が$N1個入ったTrapper's Workbenchを設置し、Camp Chairのすべての効果も得られます。近くにCampfireが必要です。\n\nCamp Chairの上に置くと、それと置き換えられます。\n\nすべてのキャンプ設備は$D1のクールダウンを共有します。", 0x6a4f5109, "u" },
  [279940] = { "治癒薬と解毒剤が入ったToxin Studyを設置し、First Aid Kitのすべての効果も得られます。近くにCampfireが必要です。\n\nFirst Aid Kitの上に置くと、それと置き換えられます。\nすべてのキャンプ設備は$D1のクールダウンを共有します。", 0xde7d7930, "u" },
  [279941] = { "特定の触媒を作れるTanning Rackを設置し、Camp Tentのすべての効果も得られます。近くにCampfireが必要です。\n\nCamp Tentの上に置くと、それと置き換えられます。すべてのキャンプ設備は$D1のクールダウンを共有します。", 0xb65c0c33, "u" },
  [279943] = { "特定の触媒を作れるSpinning Wheelを設置し、Faction Bannerのすべての効果も得られます。近くにCampfireが必要です。\n\nFaction Bannerの上に置くと、それと置き換えられます。すべてのキャンプ設備は$D1のクールダウンを共有します。", 0xade015d4, "u" },
